import React, { useEffect, useState } from 'react';

import { RangeLegendDivergentSegments } from './components/RangeLegendDivergentSegments.js';
import { RangeLegendSegments } from './components/RangeLegendSegments.js';
import { LEGEND_VARIANTS, RANGE_SORTING } from './constants.js';
import { getLegendScale } from './functions/get-legend-scale.js';
import { getVariant } from './functions/get-variant.js';
import { RangeLegendProviders } from './providers/RangeLegendProviders.js';
import { legendContainer } from './RangeLegend.sty.js';
import { defaultFormatter } from './types/default.js';
import { RangeSorting, Variant } from './types/range-legend.internal.js';
import { RangeLegendProps } from './types/range-legend.js';
import { useLegendSize } from '../shared/context/LegendSizeContext.js';

/**
 * @internal
 **/
export const RangeLegend = (props: RangeLegendProps) => {
  const {
    items,
    orientation = 'horizontal',
    formatter = defaultFormatter,
  } = props;
  const { width, height } = useLegendSize();
  const [variant, setVariant] = useState<Variant | null>(null);
  const sorting: RangeSorting =
    items[0]?.from > items[items.length - 1]?.from
      ? RANGE_SORTING.DESC
      : RANGE_SORTING.ASC;

  const scale = getLegendScale(orientation, items, width, height, sorting);

  useEffect(() => {
    if (items && items.length) {
      setVariant(getVariant(items));
    }
  }, [items]);

  if (!variant) {
    return null;
  }

  return (
    <RangeLegendProviders
      formatter={formatter}
      orientation={orientation}
      scale={scale}
      variant={variant}
      sorting={sorting}
    >
      <div
        className={legendContainer}
        style={{
          width: `${width}px`,
          height: `${height}px`,
          flexDirection: orientation === 'vertical' ? 'row' : 'column',
        }}
      >
        {variant === LEGEND_VARIANTS.DIVERGENT ? (
          <RangeLegendDivergentSegments items={items} />
        ) : (
          <RangeLegendSegments items={items} />
        )}
      </div>
    </RangeLegendProviders>
  );
};

RangeLegend['displayName'] = 'RangeLegend';
